BRD_BASELINE = "0.7"


def requirements_section(title, first, last, intro, extra=()):
    return section(title, p(intro), *[
        {"type": "requirement", **r} for r in FR
        if first <= int(r["id"][3:]) <= last or int(r["id"][3:]) in extra
    ])


